/**
 * Registers the offline shell (sw.js, generated by the web build) so the app
 * opens with no connection. A new version of the app installs in the
 * background and waits: the sync panel offers "Update now", and it also
 * applies the next time the app starts — never in the middle of a checkout.
 * The desktop app loads from its own files and needs none of this.
 */
import { useSyncExternalStore } from 'react'
import { isDesktop } from '@/lib/platform'

let waiting: ServiceWorker | null = null
let applying = false
const listeners = new Set<() => void>()
const notify = () => listeners.forEach((l) => l())

export function registerServiceWorker() {
  if (isDesktop || !import.meta.env.PROD || typeof navigator === 'undefined' || !('serviceWorker' in navigator)) return
  const sw = navigator.serviceWorker
  sw.addEventListener('controllerchange', () => {
    if (applying) window.location.reload()
  })
  void sw
    .register('/sw.js', { scope: '/' })
    .then((reg) => {
      const watch = (worker: ServiceWorker | null) => {
        worker?.addEventListener('statechange', () => {
          if (worker.state === 'installed' && sw.controller) {
            waiting = worker
            notify()
          }
        })
      }
      if (reg.waiting && sw.controller) {
        waiting = reg.waiting
        notify()
      }
      reg.addEventListener('updatefound', () => watch(reg.installing))
      // Look for a new version now and then (the app may stay open for days).
      setInterval(() => void reg.update().catch(() => undefined), 30 * 60_000)
    })
    .catch(() => undefined)
}

/** Switches to the new version now (the page reloads). */
export function applyUpdate() {
  if (!waiting) return
  applying = true
  waiting.postMessage('skip-waiting')
}

export function useUpdateReady(): boolean {
  return useSyncExternalStore(
    (l) => {
      listeners.add(l)
      return () => listeners.delete(l)
    },
    () => waiting !== null
  )
}
